const meta = generated as Record<string, { width: number; height: number; dominant: string }>;

export const INSPIRATION: InspirationAsset[] = ROWS.map(([id, title, category, colorFamilies, moods, styles, tags]) => ({
  id,
  title,
  category,
  src: asset(`/library/inspiration/${id}.jpg`),
  width: meta[id]?.width ?? 1000,
  height: meta[id]?.height ?? 1000,
  dominant: meta[id]?.dominant ?? "#E2DACD",
  colorFamilies,
  moods,
  styles,
  tags,
  license: LICENSE,
}));

